// Microbenchmark comparing add/sub/mul generated by gen_ff.py (LLVM-IR) and
// gen_ff_x64.py (x64 asm) within a single executable.
//
// Both generators emit under distinct prefixes (llvm_ / x64_) so they coexist.
// Built and run via the `bench` target in the Makefile.
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <initializer_list>
#include <vector>
#include <type_traits>
#include <mcl_fp.h>
#include <mcl/fp_def.hpp>
#include <mcl/fp_tower.hpp>
#include <cybozu/xorshift.hpp>
#include <cybozu/option.hpp>
#include <set>

//#define USE_CLK

#ifndef MCL_X64_ASM
	#undef USE_CLK
#endif

#ifdef USE_CLK
#include <cybozu/benchmark.hpp>
#include <chrono>
#include <thread>
#else
#include <chrono>
#endif

#ifdef USE_CLK
// Estimate the invariant TSC frequency by comparing rdtsc with steady_clock
// across a sleep. The sleep may oversleep (esp. on Windows); that is fine
// because the actual elapsed time is measured by the clock pair.
uint64_t getTscFreq()
{
	using namespace std::chrono;
	auto t0 = steady_clock::now();
	uint64_t c0 = cybozu::CpuClock::getCpuClk();
	std::this_thread::sleep_for(milliseconds(100));
	auto t1 = steady_clock::now();
	uint64_t c1 = cybozu::CpuClock::getCpuClk();
	double sec = duration_cast<nanoseconds>(t1 - t0).count() * 1e-9;
	return uint64_t((c1 - c0) / sec);
}
#endif

using namespace mcl;
using namespace mcl::fp;

typedef void (*FpOp)(uint64_t* z, const uint64_t* x, const uint64_t* y);
// unary low-level op (e.g. FpDbl -> Fp reduction): 2 raw arguments (z, xy).
typedef void (*FpOp1)(uint64_t* z, const uint64_t* xy);

// Number of raw pointer arguments a low-level function pointer takes.
// FpOp-like types have 3 args (binary op); FpOp1-like types have 2 (unary op).
template<class F> struct RawArity;
template<class Ret, class... Args>
struct RawArity<Ret(*)(Args...)> {
	static constexpr size_t value = sizeof...(Args);
};

// Result/Arg types and arity (2 = binary op(R&,const T&,const T&), 1 = unary
// op(R&,const T&)) of a high-level base function pointer such as Fp::add,
// FpDbl::mulPre, or FpDbl::mod.
template<class F> struct BaseTraits;
template<class R, class T>
struct BaseTraits<void(*)(R&, const T&, const T&)> {
	using Result = R;
	using Arg = T;
	static constexpr int arity = 2;
};
template<class R, class T>
struct BaseTraits<void(*)(R&, const T&)> {
	using Result = R;
	using Arg = T;
	static constexpr int arity = 1;
};

extern "C" {
	const uint8_t* llvm_get_prime();
	void llvm_add(uint64_t*, const uint64_t*, const uint64_t*);
	void llvm2_add(uint64_t*, const uint64_t*, const uint64_t*);
	void llvm_sub(uint64_t*, const uint64_t*, const uint64_t*);
	void llvm2_sub(uint64_t*, const uint64_t*, const uint64_t*);
	void llvm_mul(uint64_t*, const uint64_t*, const uint64_t*);
	// Fp2 mul (Karatsuba: 3 mulPre + 2 Montgomery reductions)
	void llvm2_mul(uint64_t*, const uint64_t*, const uint64_t*);
	// z[2N] = x[N] * y[N] (no reduction)
	void llvm_mulPre(uint64_t*, const uint64_t*, const uint64_t*);
	// z[N] = xy[2N] R^-1 mod p (Montgomery reduction)
	void llvm_mod(uint64_t*, const uint64_t*);
	// z[2N] = x[N]^2 (no reduction)
	void llvm_sqrPre(uint64_t*, const uint64_t*);
#ifdef MCL_X64_ASM
	void x64_add(uint64_t*, const uint64_t*, const uint64_t*);
	void x642_add(uint64_t*, const uint64_t*, const uint64_t*);
	void x64_sub(uint64_t*, const uint64_t*, const uint64_t*);
	void x642_sub(uint64_t*, const uint64_t*, const uint64_t*);
	void x64_mul(uint64_t*, const uint64_t*, const uint64_t*);
	// Fp2 mul (Karatsuba: 3 mulPre + 2 Montgomery reductions)
	void x642_mul(uint64_t*, const uint64_t*, const uint64_t*);
	// mulx-only variant (no adcx/adox) for pre-Broadwell CPUs
	void x64_mul_wo_adx(uint64_t*, const uint64_t*, const uint64_t*);
	// z[2N] = x[N] * y[N] (no reduction), adcx/adox rows like x64_mul
	void x64_mulPre(uint64_t*, const uint64_t*, const uint64_t*);
	// z[2N] = x[N] * y[N] (no reduction), mulx-only like x64_mul_wo_adx
	void x64_mulPre_wo_adx(uint64_t*, const uint64_t*, const uint64_t*);
	// z[N] = xy[2N] R^-1 mod p (Montgomery reduction)
	void x64_mod(uint64_t*, const uint64_t*);
	// z[2N] = x[N]^2 (no reduction), hand-scheduled mulx + add/adc
	void x64_sqrPre(uint64_t*, const uint64_t*);
#else
	#define x64_add nullptr
	#define x642_add nullptr
	#define x64_sub nullptr
	#define x642_sub nullptr
	#define x64_mul nullptr
	#define x642_mul nullptr
	#define x64_mul_wo_adx nullptr
	#define x64_mulPre nullptr
	#define x64_mulPre_wo_adx nullptr
	#define x64_mod nullptr
	#define x64_sqrPre nullptr
#endif
}

template<class T>
void initRand(Fp& x, T& rg)
{
	x.setByCSPRNG(rg);
}

template<class T>
void initRand(Fp2& x, T& rg)
{
	x.a.setByCSPRNG(rg);
	x.b.setByCSPRNG(rg);
}

template<class T>
void initRand(FpDbl& x, T& rg)
{
	Fp x0, x1;
	initRand(x0, rg);
	initRand(x1, rg);
	FpDbl::mulPre(x, x0, x1);
}


template<class F, class LowOp>
void check(const char *name, F f, std::initializer_list<LowOp> fs)
{
	using BT = BaseTraits<F>;
	using R = typename BT::Result;
	using T = typename BT::Arg;
	cybozu::XorShift rg;
	T x, y;
	R z, z0;
	const Unit *px = (const Unit*)&x;
	const Unit *py = (const Unit*)&y;
	for (int i = 0; i < 100; i++) {
		initRand(x, rg);
		initRand(y, rg);
		if constexpr (BT::arity == 2) {
			f(z, x, y);
		} else {
			f(z, x);
		}
		int idx = 0;
		for (LowOp f1 : fs) {
			if (!f1) continue;
			if constexpr (RawArity<LowOp>::value == 3) {
				f1((Unit*)&z0, px, py);
			} else {
				f1((Unit*)&z0, px);
			}
			if (z != z0) {
				fprintf(stderr, "ERR %s f1[%d]\n", name, idx);
				exit(1);
			}
			idx++;
		}
	}
}

// Time one measurement. op(k) runs the operation on stream k. P streams:
// P=1 is a serial dependency chain (latency); P=4 runs independent chains
// (throughput). The chained operands stay below p, so they do not diverge.
template<class Op>
static double measure(Op op, size_t P, size_t loop)
{
	size_t m = loop / P;
	for (size_t i = 0; i < m / 10; i++) for (size_t k = 0; k < P; k++) op(k); // warmup
#ifdef USE_CLK
	cybozu::CpuClock clk;
	clk.begin();
#else
	auto t0 = std::chrono::steady_clock::now();
#endif
	for (size_t i = 0; i < m; i++) for (size_t k = 0; k < P; k++) op(k);
#ifdef USE_CLK
	clk.end();
	return clk.getClock() / double(m * P);
#else
	auto t1 = std::chrono::steady_clock::now();
	return std::chrono::duration<double, std::nano>(t1 - t0).count() / (m * P);
#endif
}

void printRow(const char *name, const char *mode, const std::vector<double>& v) {
	printf("%-7s %-11s", name, mode);
	for (size_t i = 0; i < v.size(); i++) {
		char buf[64];
		if (i == 0) snprintf(buf, sizeof(buf), "%.3f", v[i]); // base
		else snprintf(buf, sizeof(buf), "%.3f(%.2fx)", v[i], v[i] / v[0]);
		printf(" %15s", buf);
	}
	printf("\n");
}

// Run one measurement round (P streams): time base/fs in turn, each
// writing results into b[k] from inputs a[k]/y, collecting one value per
// implementation into the returned vector. reset() is invoked before each
// individual measurement; pass a no-op when b/a don't alias (nothing to
// restore), or an actual reset when they do (b[k] overwrites a[k], so a[k]
// must be restored before the next implementation runs).
// base may be a binary op(R&,const T&,const T&) or a unary op(R&,const T&);
// each fs element may likewise be a 3-arg (z,x,y) or 2-arg (z,xy) raw
// function pointer -- arity is detected via BaseTraits/RawArity.
template<class R, class T, class Reset, class F, class LowOp>
std::vector<double> measureRound(R *b, T *a, const T& y, size_t P, size_t loop,
	F base, std::initializer_list<LowOp> fs, Reset reset)
{
	using BT = BaseTraits<F>;
	const Unit *py = (const Unit*)&y;
	std::vector<double> v;
	reset();
	if constexpr (BT::arity == 2) {
		v.push_back(measure([&](size_t k) { base(b[k], a[k], y); }, P, loop));
	} else {
		v.push_back(measure([&](size_t k) { base(b[k], a[k]); }, P, loop));
	}
	for (LowOp f : fs) {
		if (!f) {
			v.push_back(0);
			continue;
		}
		reset();
		if constexpr (RawArity<LowOp>::value == 3) {
			v.push_back(measure([&](size_t k) { f((Unit*)&b[k], (const Unit*)&a[k], py); }, P, loop));
		} else {
			v.push_back(measure([&](size_t k) { f((Unit*)&b[k], (const Unit*)&a[k]); }, P, loop));
		}
	}
	volatile Unit sink = ((const Unit*)&b[0])[0]; (void)sink;
	return v;
}

// R == T: the result can be fed back as the next input, so the chained
// calls form a true serial dependency chain, and both latency (P=1) and
// throughput (P=4) are meaningful.
// R != T (e.g. FpDbl = Fp x Fp for mulPre, or Fp = mod(FpDbl) for mod): the
// result cannot be fed back as the next input, so there is no dependency
// chain to measure; only throughput (P=4, independent streams) is
// meaningful.
template<class F, class LowOp>
void benchmark(const char *name, size_t loop, F base, std::initializer_list<LowOp> fs)
{
	using BT = BaseTraits<F>;
	using R = typename BT::Result;
	using T = typename BT::Arg;
	cybozu::XorShift rg;
	T x, y;
	initRand(x, rg);
	initRand(y, rg);
	const size_t an = 4;
	T a[an] = {};
	for (size_t k = 0; k < an; k++) a[k] = x;
	if constexpr (std::is_same_v<R, T>) {
		auto reset = [&]() { for (size_t k = 0; k < an; k++) a[k] = x; };
		auto run = [&](size_t P) { return measureRound(a, a, y, P, loop, base, fs, reset); };
		printRow(name, "latency", run(1));
		printRow(name, "throughput", run(4));
	} else {
		R dst[an] = {};
		printRow(name, "throughput", measureRound(dst, a, y, 4, loop, base, fs, [](){}));
	}
}

static const int TEST_MODE = 1<<0;
static const int BENCH_MODE = 1<<1;

template<class F, class LowOp>
void check_and_bench(int mode, const char *name, size_t loop, F base, std::initializer_list<LowOp> fs)
{
	if (mode & TEST_MODE) check(name, base, fs);
	if (mode & BENCH_MODE) benchmark(name, loop, base, fs);
}

int main(int argc, char *argv[]) {
	int mode;
	cybozu::Option opt;
	std::vector<std::string> vs;
	opt.appendVec(&vs, "set", ": select from {add,sub,add2,sub2,mul,mul2,mulPre,mod,sqrPre}");
	opt.appendOpt(&mode, TEST_MODE | BENCH_MODE, "mode", ": test(1), bench(2), both(3), default(3)");
	opt.appendHelp("h");
	if (!opt.parse(argc, argv)) {
		opt.usage();
		return 1;
	}
	opt.put();
	std::set<std::string> ss(vs.begin(), vs.end());
	const char *pStr = (const char*)llvm_get_prime();
	printf("p=%s\n", pStr);
	Fp::init(pStr, 1, 1);
	bool b;
	Fp2::init(&b);
	if (!b) {
		fprintf(stderr, "Fp2::init error\n");
		return 1;
	}

	if (mode & BENCH_MODE) {
#ifdef USE_CLK
		printf("tsc freq: %.6g GHz\n", getTscFreq() * 1e-9);
		printf("unit: tsc/op (smaller is faster); base = mcl, (Nx) = time / base\n");
#else
		printf("unit: ns/op (smaller is faster); base = mcl, (Nx) = time / base\n");
#endif
		printf("%-7s %-11s %15s %15s %15s %15s\n",
			"op", "mode", "base", "llvm", "x64", "x64woadx");
	}
#ifdef NDEBUG
	const size_t C = 200000000;
	const size_t C2 = 50000000;
#else
	const size_t C = 100;
	const size_t C2 = 100;
#endif
	if (ss.empty() || ss.find("add") != ss.end()) {
		check_and_bench(mode, "add", C, Fp::add, {llvm_add, x64_add});
	}
	if (ss.empty() || ss.find("add") != ss.end()) {
		check_and_bench(mode, "sub", C, Fp::sub, {llvm_sub, x64_sub});
	}
	if (ss.empty() || ss.find("add2") != ss.end()) {
		check_and_bench(mode, "add2", C, Fp2::add, {llvm2_add, x642_add});
	}
	if (ss.empty() || ss.find("sub2") != ss.end()) {
		check_and_bench(mode, "sub2", C, Fp2::sub, {llvm2_sub, x642_sub});
	}
	if (ss.empty() || ss.find("mul") != ss.end()) {
		check_and_bench(mode, "mul", C2, Fp::mul, {llvm_mul, x64_mul, x64_mul_wo_adx});
	}
	if (ss.empty() || ss.find("mul2") != ss.end()) {
		check_and_bench(mode, "mul2", C2, Fp2::mul, {llvm2_mul, x642_mul});
	}
	if (ss.empty() || ss.find("mulPre") != ss.end()) {
		check_and_bench(mode, "mulPre", C2, FpDbl::mulPre, std::initializer_list<FpOp>{llvm_mulPre, x64_mulPre, x64_mulPre_wo_adx});
	}
	if (ss.empty() || ss.find("mod") != ss.end()) {
		check_and_bench(mode, "mod", C2, FpDbl::mod, std::initializer_list<FpOp1>{llvm_mod, x64_mod});
	}
	if (ss.empty() || ss.find("sqrPre") != ss.end()) {
		check_and_bench(mode, "sqrPre", C2, FpDbl::sqrPre, std::initializer_list<FpOp1>{llvm_sqrPre, x64_sqrPre});
	}
}
